<!-- 模型列表页面 -->
<template>
  <div class="model">
    <div class="serch">
      <el-form class="demo-ruleForm">
        <el-form-item label="大类类型" label-width="80px">
          <el-select v-model="queryParams.model_template_config_type_id" placeholder="请选择模型类型" size="small" clearable filterable style="width: 90%" @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="'查询'+item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-search" type="primary" size="small" @click="axioss">搜索</el-button>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-plus" type="primary" size="small" @click=handleAddDialog>新增</el-button>
        </el-form-item>
      </el-form>
    </div>
    <div class="table">
      <div class="jia_table">
        <el-table 
          :data="tableData" 
          height="95%" 
          style="width: 100%" 
          :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }"
          :span-method="spanMethod"
          row-key="id"
        >
          <el-table-column prop="index" label="序号" width="100">
            <template slot-scope="scope">
              {{ ((Number(queryParams.page)-1)*Number(queryParams.per_page))+scope.$index + 1 }}
            </template>
          </el-table-column>
          <el-table-column prop="algorithm_name" label="算法"></el-table-column>
          <el-table-column prop="model_type" label="大类类型">
            <template slot-scope="scope">
              {{ findModelType(scope.row.model_template_config_type_id) }}
            </template>
          </el-table-column>
          <el-table-column prop="warning_message" label="报警信息"></el-table-column>
          <el-table-column label="操作">
            <template slot-scope="scope">
              <el-button type="text" icon="el-icon-edit" size="mini" @click="handleUpdateModel(scope.row)">修改</el-button>
              <el-button type="text" icon="el-icon-edit" size="mini" @click="handleDeleteModel(scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
      <div class="page">
        <el-pagination @current-change="handleCurrentChange" @size-change="handleSizeChange" :current-page.sync="queryParams.page" :page-size="queryParams.per_page" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="total">
        </el-pagination>
      </div>
    </div>
    <!-- 新增、修改弹窗 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="530px">
      <el-form :model="formData" ref="formData" :rules="rules" label-width="80px" class="roleForm" label-position="top">
        <el-form-item label="算法" prop="algorithm_name">
          <el-input v-model="formData.algorithm_name" autocomplete="off" placeholder="请输入算法"></el-input>
        </el-form-item>
        <el-form-item label="大类类型" prop="model_template_config_type_id">
          <el-select v-model="formData.model_template_config_type_id" placeholder="请选择大类类型" clearable filterable style="width: 100%" @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="报警信息" prop="warning_message">
          <el-input v-model="formData.warning_message" type="textarea" :rows="2" autocomplete="off" placeholder="报警信息"></el-input>
        </el-form-item>
      </el-form>

      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="handleSubmit">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
<script>
import { modelApi } from '@/api/model';
import { dictApi } from '@/api/system/dict';
import { MessageBox } from 'element-ui'

export default {
  data() {
    return {
      // 表格相关数据
      tableData: [],
      queryParams: {
        page: 1,
        per_page: 15,
        model_type: '',
        model_template_config_type_id: '',
      },
      total: 0,
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      modelTypeOptions: [],
      // 新增、修改相关数据
      dialogTitle: '',
      dialogVisible: false,
      formData: {
        algorithm_name: '',
        model_type: '',
        model_template_config_type_id: '',
        model_conf_list: '',
        warning_message: '',
      },
      modelListArr: [{ value: '' }],
      rules: {
        algorithm_name: [
          { required: true, message: '请输入算法', trigger: 'blur' }
        ],
        model_type: [
          { required: true, message: '请选择模型类型', trigger: 'change' }
        ],
        model_template_config_type_id: [
          { required: true, message: '请选择大类类型', trigger: 'change' }
        ],
        warning_message: [
          { required: true, message: '请输入报警信息', trigger: 'change' }
        ]
      },
      config: {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      },
      // 存储合并行的信息
      mergeMap: {}
    };
  },
  created() {
    this.getModelType();
  },
  mounted() {
    this.axioss();
  },
  methods: {
    // 页码变化
    handleCurrentChange(val) {
      this.queryParams.page = val;
      this.axioss();
    },
    // 当前页数据条数变化
    handleSizeChange(val) {
      this.queryParams.per_page = val;
      this.axioss();
    },
    // 查询表格数据   
    axioss() {
      this.$http.get(modelApi.model_warnmessage_show, {
        params: this.queryParams
      }).then(response => {
        this.tableData = response.data.data.data
        this.total = response.data.data.pagination.total_items
        // 数据更新后重新计算合并行
        this.calculateMerge()
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 计算需要合并的行
    calculateMerge() {
      const mergeMap = {}
      let index = 0
      while (index < this.tableData.length) {
        const currentItem = this.tableData[index]
        let rowSpan = 1
        // 找到所有相同 algorithm_name 的行
        for (let i = index + 1; i < this.tableData.length; i++) {
          if (this.tableData[i].algorithm_name === currentItem.algorithm_name) {
            rowSpan++
          } else {
            break
          }
        }
        // 记录该组数据的起始索引和行数
        mergeMap[index] = rowSpan
        index += rowSpan
      }
      this.mergeMap = mergeMap
    },
    // 行合并方法
    spanMethod({ row, column, rowIndex, columnIndex }) {
      // 只对算法列（第2列，索引为1）进行合并
      if (columnIndex === 1) {
        const rowSpan = this.mergeMap[rowIndex]
        if (rowSpan) {
          return {
            rowspan: rowSpan,
            colspan: 1
          }
        } else {
          return {
            rowspan: 0,
            colspan: 0
          }
        }
      }
      return {
        rowspan: 1,
        colspan: 1
      }
    },
    // 查询，模型类型、大类
    getModelType() {
      this.$http.get(modelApi.getModelType, {
        params: {
          page: 1,
          per_page: 999
        }
      }).then(response => {
        this.modelTypeOptions = response.data.data.data
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 翻译大类
    findModelType(id) {
      let res = this.modelTypeOptions.find(v => v.id == id)
      return res ? res.model_type_name : id
    },
    //打开新增弹窗
    handleAddDialog() {
      this.dialogVisible = true
      this.dialogTitle = "新增模型"
      this.modelListArr = [{ value: '' }]
      this.formData = {
        algorithm_name: '',
        model_type: '',
        model_template_config_type_id: '',
        warning_message: '',
      }
    },
    // 新增、修改确定按钮
    handleSubmit() {
      this.$refs.formData.validate((valid) => {
        if (valid) {
          let form = new FormData();
          Object.keys(this.formData).forEach(key => {
            form.append(key, this.formData[key]);
          });
          const axiosUrl = this.dialogTitle === '新增模型' ? modelApi.model_warn_maessage_add : modelApi.model_warn_maessage_update
          this.$http.post(axiosUrl, form, this.config)
            .then(response => {
              if (response.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: response.data.msg
                })
                this.dialogVisible = false
              } else {
                this.$message({
                  type: 'warning',
                  message: response.data.msg
                })
                this.dialogVisible = false
              }
              this.axioss()
            })
            .catch(rek => {
              console.log(rek)
            })
        }
      })
    },
    // 自定义内容加号+
    handleAddList() {
      this.modelListArr.push({ value: '' })
    },
    // 自定义内容减号-
    handleDeleteList(index) {
      this.modelListArr.splice(index, 1)
    },
    // 表格中修改按钮
    handleUpdateModel(row) {
      this.formData = row
      this.dialogTitle = '修改模型'
      this.dialogVisible = true
    },
    // 表格中删除按钮
    handleDeleteModel(row) {
      MessageBox.confirm('确定删除该模型吗？', '提示', {
        type: 'warning'
      }).then(() => {
        let data = {
          id: row.id
        }
        let form = new FormData()
        Object.keys(data).forEach(key => {
          form.append(key, data[key]);
        });
        this.$http.post(modelApi.model_warning_message_delete, form, this.config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: 'success',
                message: response.data.msg
              })
            } else {
              this.$message({
                type: 'warning',
                message: response.data.msg
              })
            }
            this.axioss();
          })
          .catch(rek => {
            console.log(rek)
          })
      }).catch(() => {
        this.$message.info('已取消删除');
      });
    }
  }
};
</script>
  
